export function assertPlayerIntelSourceTransfer(file, input) {
  const text = normalize(input), proof = PLAYER_INTEL_SOURCE_TRANSFER;
  assert(Object.hasOwn(proof.currentPins, file), 'Unknown intel source compatibility file');
  assert.equal(hash(text), proof.currentPins[file], 'Intel source changed: ' + file);
  assert.equal(blob(text), proof.currentBlobs[file], 'Intel complete Git blob changed: ' + file);
  let baselineText = text;
  for (const chunk of proof.inverses[file]) {
    assert.equal(baselineText.split(chunk.current).length, 2, 'Intel inverse must be exact and unique: ' + file);
    baselineText = baselineText.replace(chunk.current, () => chunk.baseline);
  }
  assert.equal(hash(baselineText), proof.baselinePins[file], 'Intel source differs beyond frozen hunks: ' + file);
  assert.equal(blob(baselineText), proof.baselineBlobs[file], 'Intel complete predecessor blob differs: ' + file);
  return { ...proof, file, baselineText, inverseChunks: proof.inverses[file].length };
}

// Unknown bytes remain intact for the original rejecting guard; no pattern grants authority.
export function playerIntelSourceBaseline(file, input) {
  const text = normalize(cityGameplaySourceBaseline(file, input)), pins = PLAYER_INTEL_SOURCE_TRANSFER.currentPins;
  return Object.hasOwn(pins, file) && hash(text) === pins[file]
    ? assertPlayerIntelSourceTransfer(file, text).baselineText : text;
}
